import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>AVIF ve JPG, iki kuşağın formatlarıdır. AVIF yeni, küçük ve yetenekli; JPG eski, evrensel ve her yerde açılır.</p>\n<p>Doğru seçim, görselin nerede kullanılacağına bağlıdır. Web için doğru olan, form için yanlış olabilir; arşiv için doğru olan, e-posta için yanlış olabilir.</p>\n<p>Bu yazı iki formatı boyut, kalite, HDR, saydamlık ve destek açısından karşılaştırıyor; sonunda hangisini ne zaman kullanacağınız belli olacak.</p>\n<h2 id=\"avif-at-a-glance\">AVIF'e bir bakışta</h2>\n<p>AVIF, 2019'da tanıtılan modern bir formattır. AV1 video codec'ine dayanır ve olağanüstü sıkıştırma sunar.</p>\n<p>AVIF'in gücü verimliliktir. Aynı kalitede JPG'den yüzde 30-50 daha küçük dosyalar üretir.</p>\n<p>AVIF ayrıca HDR, geniş renk gamı ve saydamlığı destekler. Tek format, birçok yeteneği bir arada sunar.</p>\n<h2 id=\"jpg-at-a-glance\">JPG'ye bir bakışta</h2>\n<p>JPG, 1992'den beri var ve her yerde destekleniyor. Otuz yıllık destek, onu evrensel format yaptı.</p>\n<p>JPG'nin gücü uyumluluktur. Her program, her form, her yazıcı JPG'yi açar.</p>\n<p>Zayıf yanı verimliliktir. JPG, aynı görseli AVIF'ten çok daha fazla baytla saklar.</p>\n<h2 id=\"file-size-compared\">Dosya boyutu: AVIF kesin kazanır</h2>\n<p>Bu kategoride AVIF açık ara kazanır. Aynı fotoğraf AVIF olarak yarıya inebilir.</p>\n<p>Fark, görsel sayısı arttıkça büyür. Yirmi görselli bir sayfada toplam kazanç birkaç MB olabilir.</p>\n<p>JPG yalnızca çok küçük dosyalarda rekabet eder. Birkaç KB'lık görsellerde fark önemsizdir.</p>\n<h2 id=\"quality-compared\">Görsel kalitesi: AVIF açık kazanır</h2>\n<p>Aynı dosya boyutunda AVIF daha iyi görünür. Daha az bozulma, daha temiz renk geçişleri sunar.</p>\n<p>Aynı kalitede AVIF daha küçüktür. Bu iki yönlü avantaj, AVIF'i web için ideal kılar.</p>\n<p>Fark, düşük boyutlarda daha belirgindir. Küçük dosyalarda JPG bozulur; AVIF temiz kalır.</p>\n<h2 id=\"hdr-and-colour\">HDR ve geniş renk gamı</h2>\n<p>AVIF HDR fotoğrafları saklayabilir; JPG saklayamaz. Geniş renk gamı da yalnızca AVIF'te vardır.</p>\n<p>Çoğu ekranda fark görülmez. Standart ekranlar HDR göstermez; bu yüzden kazanç pratikte sınırlıdır.</p>\n<p>Profesyonel işlerde AVIF önemlidir. Fotoğrafçılar ve tasarımcılar, renk doğruluğu için AVIF'i tercih eder.</p>\n<h2 id=\"transparency-compared\">Saydamlık: AVIF tamamen kazanır</h2>\n<p>AVIF saydamlığı destekler; JPG desteklemez. Saydam logo AVIF olarak saklanabilir, JPG olarak saklanamaz.</p>\n<p>Bu, AVIF'i PNG'nin yerini alabilecek tek format yapar. Saydamlık ve küçük boyut bir aradadır.</p>\n<p>Saydam görsel için JPG kullanmayın. Saydam alanlar beyazla dolar ve logo bozulur.</p>\n<h2 id=\"browser-support\">Tarayıcı desteği: AVIF hızla yetişiyor</h2>\n<p>Modern tarayıcıların tamamı AVIF destekler. Chrome, Firefox, Safari ve Edge AVIF gösterir.</p>\n<p>Eski tarayıcı payı artık çok küçüktür. Çoğu site için AVIF kullanmak güvenlidir.</p>\n<p>Picture öğesiyle JPG yedeği sunun. Modern tarayıcılar AVIF alır, eskiler yedeği kullanır.</p>\n<h2 id=\"other-support\">Tarayıcı dışındaki destek</h2>\n<p>Tarayıcı dışında JPG açık ara öndedir. Ofis programları, e-posta istemcileri ve eski yazılımlar JPG'yi açar.</p>\n<p>AVIF, Windows ve macOS'un yeni sürümlerinde açılır ama eski sürümlerde açılmaz. Formlar genellikle AVIF kabul etmez.</p>\n<p>Dosya tarayıcı dışına çıkacaksa JPG kullanın. Uyumluluk, boyut kazancından önemlidir.</p>\n<h2 id=\"when-to-use-avif\">AVIF ne zaman kullanılmalı?</h2>\n<p>Web sitesi görsellerinde AVIF kullanın. Hız kazancı gerçektir ve ziyaretçiler farkı hisseder.</p>\n<p>Fotoğraf arşivinde AVIF kullanın. En küçük ve en kaliteli sürüm, arşiv için idealdir.</p>\n<p>HDR fotoğraflarda AVIF kullanın. JPG, HDR bilgisini saklayamaz.</p>\n<h2 id=\"when-to-use-jpg\">JPG ne zaman kullanılmalı?</h2>\n<p>Paylaşım için JPG kullanın. Alıcının programı bilinmiyorsa JPG her zaman açılır.</p>\n<p>Form ve e-posta için JPG kullanın. Bu sistemler AVIF kabul etmez; JPG her zaman geçer.</p>\n<p>Baskı için JPG kullanın. Baskı merkezleri JPG'yi kabul eder; AVIF'i reddedebilir.</p>\n<h2 id=\"converting-between-them\">İkisi arasında dönüştürme</h2>\n<p>AVIF'den JPG'ye dönüştürme kolaydır. Kaliteyi yüzde 85 tutun; saydam alanlar için arka plan rengi seçin.</p>\n<p>JPG'den AVIF'e dönüştürme de kolaydır ama kayıp geri gelmez. JPG'de kaybolan ayrıntı, AVIF'te geri kazanılmaz.</p>\n<p>Her iki yönde de orijinalleri saklayın. Dönüştürme zinciri kalite kaybettirir; üretimi her zaman kaynaktan yapın.</p>\n<h2 id=\"verdict\">Karar: hangi format kazanıyor?</h2>\n<p>Web için AVIF kazanıyor. Daha küçük dosyalar, daha iyi kalite ve HDR desteği; kazanç açık.</p>\n<p>Uyumluluk için JPG kazanıyor. Her yerde açılır ve hiçbir sistem onu reddetmez.</p>\n<p>Doğru cevap ikisini de kullanmaktır. Web için AVIF, paylaşım ve arşiv için JPG; format hedefe göre seçilir.</p>\n<h2 id=\"avif-jpg-social\">Sosyal medya için AVIF ve JPG</h2>\n<p>Sosyal platformlar yüklenen görseli genelde kendi formatına çevirir. Yükleme formatı sonucu pek etkilemez.</p>\n<p>Yine de JPG yüklemek daha güvenlidir. Platform ne olursa olsun, JPG dosyası kabul edilir.</p>\n<p>Platformun boyut isteğine dikkat edin. Yanlış boyut kırpılır; format burada ikincil konudur.</p>\n<h2 id=\"avif-jpg-ecommerce\">E-ticaret için AVIF ve JPG</h2>\n<p>Ürün görsellerinde AVIF hız kazandırır. Hızlı sayfalar daha çok satış getirir.</p>\n<p>Ürün fotoğraflarında kalite kritiktir. AVIF, aynı boyutta JPG'den daha iyi görünür.</p>\n<p>Eski tarayıcılar için JPG yedeği sunun. Picture öğesi, her ziyaretçinin görseli görmesini sağlar.</p>\n<h2 id=\"avif-jpg-news\">Haberler için AVIF ve JPG</h2>\n<p>Haber siteleri AVIF'i sever. Onlarca görseli olan sayfalarda toplam kazanç çok büyüktür.</p>\n<p>Haber fotoğrafları hızlı yüklenmelidir. Okur beklemez; yavaş sayfa okur kaybettirir.</p>\n<p>Arşiv için AVIF saklayın. En küçük ve en kaliteli sürüm, arşiv için idealdir.</p>\n<h2 id=\"avif-jpg-photography\">Fotoğrafçılık için AVIF ve JPG</h2>\n<p>Fotoğrafçılar için AVIF, geleceğin formatıdır. HDR ve geniş renk gamı, fotoğrafın hakkını verir.</p>\n<p>Müşteri tesliminde JPG kullanın. Müşterinin programı ne olursa olsun, dosya açılır.</p>\n<p>Çekimlerinizi AVIF ya da RAW olarak arşivleyin. JPG yalnızca paylaşım kopyasıdır.</p>\n<h2 id=\"format-race-ahead\">Önümüzdeki format yarışı</h2>\n<p>Format yarışı devam ediyor. AVIF bugün önde ama JPEG XL sırada bekliyor.</p>\n<p>JPG ise her zaman yedek kalacak. Otuz yıllık destek, onu evrensel format yaptı.</p>\n<p>Strateji basittir: orijinalleri en iyi formatta saklayın, her hedef için kopya üretin. Format değişse bile orijinalden yeni kopya üretebilirsiniz.</p>\n<p>Sonuç basit: web için AVIF, her yer için JPG. Adımlar için <a href=\"/tr/blog/avif-jpg-ye-nasil-donusturulur\">AVIF JPG'ye nasıl dönüştürülür</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/avif-jpg-ye-donustur-rehberi\">AVIF'den JPG'ye kılavuzunda</a>. Dönüştürmek için <a href=\"/tr/avif-jpg-ye-donustur\">AVIF'den JPG'ye aracını</a> açın; ters yön için <a href=\"/tr/jpg-webp-ye-donustur\">JPG'den WebP'ye dönüştürücü</a> hazırdır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"AVIF, JPG'den daha mı iyi kaliteye sahip?","answer":"Evet, aynı dosya boyutunda AVIF daha iyi görünür; daha az bozulma ve daha temiz renk geçişleri sunar. Aynı kalitede ise AVIF daha küçüktür. Fark, küçük dosyalarda daha belirgindir; düşük boyutlarda JPG bozulur, AVIF temiz kalır."},{"question":"Fotoğraflarımı AVIF olarak mı saklamalıyım, yoksa hepsini JPG'ye mi dönüştürmeliyim?","answer":"Arşiv için AVIF saklayın; en küçük ve en kaliteli sürümdür, HDR bilgisini de korur. Paylaşım için JPG'ye dönüştürün; alıcının programı bilinmiyorsa JPG her zaman açılır. Kural basit: arşiv AVIF, paylaşım JPG."},{"question":"Windows, AVIF dosyalarını dönüştürmeden açabilir mi?","answer":"Windows 10 ve 11'in güncel sürümleri AVIF açabilir; eski sürümler açamaz. Emin değilseniz dosyayı JPG'ye dönüştürün. Dönüştürülen JPG her Windows sürümünde açılır."},{"question":"Bir web sitesi için hangi format daha iyi, AVIF mi JPG mi?","answer":"AVIF daha iyidir: dosyalar yarı yarıya küçülür ve sayfalar hızlanır. Modern tarayıcıların tamamı AVIF destekler. Eski tarayıcılar için picture öğesiyle JPG yedeği sunun; her ziyaretçi görseli görür."},{"question":"AVIF, PNG gibi saydamlığı destekler mi?","answer":"Evet. AVIF alfa kanalını destekler; saydam logolar AVIF olarak saklanabilir. JPG saydamlığı desteklemez; saydam alanlar beyazla dolar. Saydamlık ve küçük boyut bir arada isteniyorsa AVIF doğru seçimdir."},{"question":"AVIF bir gün JPG'nin yerini alacak mı?","answer":"Web'de büyük ölçüde aldı bile; ama tamamen alması beklenmiyor. JPG otuz yıldır her yerde açılıyor ve uyumluluk için vazgeçilmez. AVIF web'in formatı, JPG ise evrensel yedek olmaya devam edecek."}];
